"""Bounded native model comparison with train-only features and nested time tests."""
from __future__ import annotations

import warnings
from dataclasses import dataclass

import numpy as np
import pandas as pd
from sklearn.ensemble import GradientBoostingRegressor, RandomForestRegressor
from sklearn.linear_model import Ridge
from sklearn.preprocessing import StandardScaler
from src.quantlib.crossvalidation import detect_boundary_leakage, purged_walk_forward_splits
from src.quantlib.multipletesting import benjamini_hochberg

VERSION = "mona-adaptive-walkforward-v3"
MODEL_NAMES = {"zero": "暂无方向预测", "ridge_1": "正则回归", "ridge_20": "正则回归",
               "ridge_100": "正则回归", "forest": "随机森林", "boosting": "梯度提升", "blend": "多方法组合"}
BASE_MODELS = ("ridge_1", "ridge_20", "ridge_100", "forest", "boosting")


class FeatureTransform:
    """Fit missingness, clipping, target ranking and redundancy on training only."""

    def fit(self, x: pd.DataFrame, y: np.ndarray):
        x = x.replace([np.inf, -np.inf], np.nan)
        usable = x.columns[(x.notna().mean() >= .8) & (x.nunique() > 2)]
        self.medians = x[usable].median()
        filled = x[usable].fillna(self.medians)
        self.lower, self.upper = filled.quantile(.01), filled.quantile(.99)
        clipped = filled.clip(self.lower, self.upper, axis=1)
        ranks = clipped.rank()
        target = pd.Series(y, index=x.index).rank()
        importance = ranks.corrwith(target).abs().fillna(0)
        order = sorted(usable, key=lambda name: (-importance[name], name))
        self.names = []
        maximum = min(30, max(4, len(x) // 12))
        for name in order:
            if importance[name] <= 0:
                continue
            if self.names and ranks[self.names].corrwith(ranks[name]).abs().max() > .85:
                continue
            self.names.append(name)
            if len(self.names) >= maximum:
                break
        self.scaler = StandardScaler()
        if self.names:
            self.scaler.fit(self._values(x))
        return self

    def _values(self, x):
        return x[self.names].replace([np.inf, -np.inf], np.nan).fillna(self.medians[self.names]).clip(
            self.lower[self.names], self.upper[self.names], axis=1).to_numpy(dtype=float)

    def transform(self, x):
        return self.scaler.transform(self._values(x)) if self.names else np.empty((len(x), 0))


def _model(name):
    if name.startswith("ridge_"):
        return Ridge(alpha=float(name.split("_")[1]))
    if name == "forest":
        return RandomForestRegressor(n_estimators=80, max_depth=5, min_samples_leaf=15,
                                     max_features=.8, random_state=41, n_jobs=1)
    return GradientBoostingRegressor(n_estimators=70, max_depth=2, min_samples_leaf=15,
                                     learning_rate=.04, loss="huber", random_state=41)


@dataclass
class FittedModel:
    name: str
    transform: FeatureTransform | None
    models: list

    def predict(self, x):
        if self.name == "zero":
            return np.zeros(len(x))
        values = self.transform.transform(x)
        return np.mean([model.predict(values) for model in self.models], axis=0)


def _fit(name, x, y):
    if name == "zero":
        return FittedModel(name, None, [])
    transform = FeatureTransform().fit(x, y)
    if not transform.names:
        raise ValueError("no usable training features")
    names = ("ridge_20", "forest", "boosting") if name == "blend" else (name,)
    models = [_model(item).fit(transform.transform(x), y) for item in names]
    return FittedModel(name, transform, models)


def training_samples(frame, features, horizon, intraday):
    target = frame["close"].shift(-horizon) / frame["close"] - 1
    valid = target.notna() & np.isfinite(target)
    if intraday:
        valid &= frame["day"] == frame["day"].shift(-horizon)
        valid &= frame["position"].shift(-horizon) - frame["position"] == horizon
    positions = np.flatnonzero(valid.to_numpy())
    if positions.size and positions[-1] + horizon >= len(frame):
        raise ValueError("training outcome exceeds observation cutoff")
    return positions, features.iloc[positions], target.iloc[positions].to_numpy()


def time_splits(frame, positions, horizon, intraday, *, selection=False):
    if intraday:
        days = frame.iloc[positions]["day"].to_numpy()
        for day in sorted(set(days))[2:][-2:]:
            train, test = np.flatnonzero(days < day), np.flatnonzero(days == day)
            if len(train) >= 100 and len(test) >= 30:
                yield train, test
    else:
        ends = np.searchsorted(positions, positions + horizon, side="right") - 1
        for split in purged_walk_forward_splits(len(positions), ends, n_folds=5 if selection else 3):
            if not detect_boundary_leakage(split, ends, len(positions)).clean:
                raise ValueError("time split leakage")
            if len(split.train) >= 80 and len(split.test) >= 30:
                if positions[split.train].max() + horizon >= positions[split.test].min():
                    raise ValueError("label boundary leakage")
                yield split.train, split.test


def _improvement_pvalue(difference, positions, frame, horizon, intraday, fold_ids):
    """Centered moving-block bootstrap; a historical test, not future confidence."""
    block = max(10, horizon * 2)
    boundaries = (np.diff(positions) != 1) | (np.diff(fold_ids) != 0)
    if intraday:
        days = frame.iloc[positions]["day"].to_numpy()
        boundaries |= days[1:] != days[:-1]
    segments = np.split(difference, np.flatnonzero(boundaries) + 1)
    if sum(len(segment) // block for segment in segments) < 6 or difference.mean() <= 0:
        return 1.0
    rng = np.random.default_rng(103 + horizon)
    samples = np.zeros(399)
    for segment in segments:
        width = min(block, len(segment))
        windows = np.lib.stride_tricks.sliding_window_view(segment - difference.mean(), width)
        starts = rng.integers(len(windows), size=(399, (len(segment) + width - 1) // width))
        draws = windows[starts].reshape(399, -1)[:, :len(segment)]
        samples += draws.sum(axis=1)
    samples /= len(difference)
    samples -= samples.mean()
    return float((1 + np.sum(samples >= difference.mean())) / 400)


def select_model(frame, positions, x, y, horizon, intraday):
    """Inner validation selects the algorithm; no outer-test values are read."""
    predicted = {name: [] for name in ("zero", *BASE_MODELS, "blend")}
    truth, tested, tested_folds, fold_scores, failures = [], [], [], [], {}
    for train, test in time_splits(frame, positions, horizon, intraday, selection=True):
        transform = FeatureTransform().fit(x.iloc[train], y[train])
        xt, xv = transform.transform(x.iloc[train]), transform.transform(x.iloc[test])
        fold_predictions = {"zero": np.zeros(len(test))}
        for name in BASE_MODELS:
            try:
                if not transform.names:
                    raise ValueError("no usable features")
                fold_predictions[name] = _model(name).fit(xt, y[train]).predict(xv)
            except (ValueError, np.linalg.LinAlgError) as exc:
                failures[name] = type(exc).__name__
        if all(name in fold_predictions for name in ("ridge_20", "forest", "boosting")):
            fold_predictions["blend"] = np.mean([fold_predictions[name] for name in ("ridge_20", "forest", "boosting")], axis=0)
        truth.extend(y[test].tolist())
        tested.extend(positions[test].tolist())
        tested_folds.extend([len(fold_scores)] * len(test))
        fold_scores.append({name: float(np.mean(np.abs(y[test] - values))) for name, values in fold_predictions.items()})
        for name in predicted:
            predicted[name].extend(fold_predictions.get(name, np.full(len(test), np.nan)).tolist())
    if len(truth) < 60 or len(fold_scores) < 2:
        return "zero", {"reason": "insufficient_inner_folds", "candidates": [], "folds": len(fold_scores)}
    truth, tested = np.asarray(truth), np.asarray(tested)
    base_loss = np.abs(truth)
    candidates, pvalues = [], []
    for name, values in predicted.items():
        values = np.asarray(values)
        if not np.isfinite(values).all():
            continue
        loss = np.abs(truth - values)
        pvalue = 1.0 if name == "zero" else _improvement_pvalue(base_loss - loss, tested, frame, horizon, intraday, tested_folds)
        candidates.append({"id": name, "mae": float(loss.mean()), "p_value": pvalue,
                           "fold_wins": sum(scores.get(name, np.inf) < scores["zero"] for scores in fold_scores)})
        if name != "zero":
            pvalues.append(pvalue)
    challengers = [candidate for candidate in candidates if candidate["id"] != "zero"]
    if challengers:
        corrected = benjamini_hochberg(pvalues, fdr=.1)
        for candidate, q in zip(challengers, corrected.adjusted_p_values, strict=True):
            candidate["adjusted_p_value"] = float(q)
    eligible = [candidate for candidate in challengers if candidate["adjusted_p_value"] <= .1
                and candidate["fold_wins"] > len(fold_scores) / 2 and candidate["mae"] < base_loss.mean()]
    chosen = min(eligible, key=lambda item: (item["mae"], item["id"]))["id"] if eligible else "zero"
    return chosen, {"reason": "historical_improvement" if eligible else "no_stable_improvement",
                    "candidates": candidates, "folds": len(fold_scores), "samples": len(truth),
                    "multiple_testing": "moving_block_bootstrap_399_BH_0.1", "fit_failures": failures}


def fit_horizon(frame, features, horizon, intraday):
    positions, x, y = training_samples(frame, features, horizon, intraday)
    if len(positions) < 240:
        raise ValueError("insufficient labeled observations")
    outer = list(time_splits(frame, positions, horizon, intraday))
    if len(outer) < 2:
        raise ValueError("insufficient independent time windows")
    calibration, outer_records, heldout = [], [], None
    final_test_first = positions[outer[-1][1][0]]
    calibration_last_outcome = None
    for index, (train, test) in enumerate(outer):
        chosen, selection = select_model(frame, positions[train], x.iloc[train], y[train], horizon, intraday)
        model = _fit(chosen, x.iloc[train], y[train])
        predicted = model.predict(x.iloc[test])
        residuals = y[test] - predicted
        outer_records.append({"training_last_position": int(positions[train][-1]),
                              "test_first_position": int(positions[test][0]), "test_last_position": int(positions[test][-1]),
                              "model": chosen, "features": model.transform.names if model.transform else [],
                              "selection": selection, "samples": len(test)})
        if index == len(outer) - 1:
            heldout = {"mae": float(np.mean(np.abs(residuals))), "baseline_mae": float(np.mean(np.abs(y[test]))),
                       "direction_accuracy": float(np.mean(np.sign(predicted) == np.sign(y[test]))),
                       "samples": len(test), "model_id": chosen,
                       "selection_validated": selection.get("folds", 0) >= 2 and selection.get("samples", 0) >= 60,
                       "start": str(frame.iloc[positions[test][0]].get("trade_date", frame.index[positions[test][0]])),
                       "end": str(frame.iloc[positions[test][-1]].get("trade_date", frame.index[positions[test][-1]]))}
        else:
            before_holdout = positions[test] + horizon < final_test_first
            calibration.extend(residuals[before_holdout].tolist())
            if before_holdout.any():
                calibration_last_outcome = int((positions[test][before_holdout] + horizon).max())
    # Keep the family selected before the final holdout. Refitting known data
    # may update its parameters, but cannot substitute an untested family.
    published = chosen if heldout["mae"] < heldout["baseline_mae"] else "zero"
    final = _fit(published, x, y)
    band = [float(value) for value in np.quantile(calibration, [.1, .9])] if len(calibration) >= 40 else None
    validation = {**heldout, "step": horizon, "folds": len(outer),
                  "beat_baseline": heldout["mae"] < heldout["baseline_mae"],
                  "interval_coverage": float(np.mean((residuals >= band[0]) & (residuals <= band[1]))) if band else None,
                  "calibration_samples": len(calibration), "calibration_excludes_holdout": True}
    return {"model": final, "band": band, "validation": validation, "training_rows": len(x),
            "audit": {"outer_folds": outer_records, "final_selection": selection,
                      "selected_challenger": chosen, "published_model": published,
                      "selection_last_outcome_position": int(positions[train][-1] + horizon),
                      "deployment_rule": "freeze family before final holdout, publish only if it beats zero-return, then refit same family on observed labels",
                      "calibration_last_outcome_position": calibration_last_outcome,
                      "final_features": final.transform.names if final.transform else [],
                      "training_last_outcome_position": int(positions[-1] + horizon)}}


def build_models(frame, features, horizons, intraday, progress=None):
    models = {}
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        for horizon in horizons:
            if progress:
                progress("validation")
            models[horizon] = fit_horizon(frame, features, horizon, intraday)
    return models

