        return self

    def _values(self, x):
        return x[self.names].replace([np.inf, -np.inf], np.nan).fillna(self.medians[self.names]).clip(
            self.lower[self.names], self.upper[self.names], axis=1).to_numpy(dtype=float)

    def transform(self, x):
        return self.scaler.transform(self._values(x)) if self.names else np.empty((len(x), 0))


def _model(name):
    if name == "forest":
        return RandomForestClassifier(n_estimators=100, max_depth=5, random_state=42, n_jobs=1)
    if name == "boosting":
        return GradientBoostingClassifier(n_estimators=100, max_depth=3, learning_rate=.05, random_state=42)
    if name == "logistic":
        return LogisticRegression(C=1., max_iter=1000, random_state=42)
    raise ValueError("unknown direction classifier")


def _distribution(y):
    positive = y > 0
    return {"positive_mean": float(y[positive].mean()) if positive.any() else 0.,
            "nonpositive_mean": float(y[~positive].mean()) if (~positive).any() else 0.,
            "positive_fraction": float(positive.mean()), "positive_count": int(positive.sum()),
            "nonpositive_count": int((~positive).sum())}


@dataclass
class FittedModel:
    name: str
    transform: FeatureTransform | None
    models: list
    return_distribution: dict

    def predict_probability(self, x):
        if self.name == "historical_distribution":
            return np.full(len(x), self.return_distribution["positive_fraction"])
        values = self.transform.transform(x)
        probabilities = []
        for model in self.models:
            positive = np.flatnonzero(np.asarray(model.classes_) == 1)
            probabilities.append(model.predict_proba(values)[:, positive[0]] if len(positive) else np.zeros(len(x)))
        return np.clip(np.mean(probabilities, axis=0), 0., 1.)

    def predict(self, x):
        probability = self.predict_probability(x)
        return (probability * self.return_distribution["positive_mean"]
                + (1 - probability) * self.return_distribution["nonpositive_mean"])


def _fit(name, x, y, transform=None):
    distribution = _distribution(y)
    labels = (y > 0).astype(int)
    if np.unique(labels).size < 2:
        return FittedModel("historical_distribution", None, [], distribution)
    transform = transform or FeatureTransform().fit(x, labels)
    if not transform.names:
        return FittedModel("historical_distribution", None, [], distribution)
    names = BASE_MODELS if name == "blend" else (name,)
    models = [_model(item).fit(transform.transform(x), labels) for item in names]
    return FittedModel(name, transform, models, distribution)


def training_samples(frame, features, horizon, intraday):
    target = frame["close"].shift(-horizon) / frame["close"] - 1
    valid = target.notna() & np.isfinite(target)
    if intraday:
        valid &= frame["day"] == frame["day"].shift(-horizon)
        valid &= frame["position"].shift(-horizon) - frame["position"] == horizon
    positions = np.flatnonzero(valid.to_numpy())
    if positions.size and positions[-1] + horizon >= len(frame):
        raise ValueError("training outcome exceeds observation cutoff")
    return positions, features.iloc[positions], target.iloc[positions].to_numpy()


def time_splits(frame, positions, horizon, intraday, *, selection=False):
    if intraday:
        days = frame.iloc[positions]["day"].to_numpy()
        for day in sorted(set(days))[2:][-2:]:
            train, test = np.flatnonzero(days < day), np.flatnonzero(days == day)
            if len(train) >= 50 and len(test) >= 30:
                yield train, test
    else:
        ends = np.searchsorted(positions, positions + horizon, side="right") - 1
        for split in purged_walk_forward_splits(len(positions), ends, n_folds=5 if selection else 3):
            if not detect_boundary_leakage(split, ends, len(positions)).clean:
                raise ValueError("time split leakage")
            if len(split.train) >= 50 and len(split.test) >= 30:
                if positions[split.train].max() + horizon >= positions[split.test].min():
                    raise ValueError("label boundary leakage")
                yield split.train, split.test


def _direction_metrics(y, predicted):
    actual, direction = y > 0, predicted > 0
    balanced = (float(np.mean([np.mean(direction[actual] == actual[actual]),
                              np.mean(direction[~actual] == actual[~actual])]))
                if actual.any() and (~actual).any() else None)
    return {"direction_accuracy": float(np.mean(actual == direction)),
            "balanced_direction_accuracy": balanced}


def select_model(frame, positions, x, y, horizon, intraday):
    """Select direction accuracy on inner windows, without a baseline publication gate."""
    predicted = {name: [] for name in (*BASE_MODELS, "blend")}
    probabilities = {name: [] for name in predicted}
    truth, folds = [], 0
    for train, test in time_splits(frame, positions, horizon, intraday, selection=True):
        transform = FeatureTransform().fit(x.iloc[train], (y[train] > 0).astype(int))
        fitted = {name: _fit(name, x.iloc[train], y[train], transform) for name in BASE_MODELS}
        if all(model.name != "historical_distribution" for model in fitted.values()):
            fitted["blend"] = FittedModel("blend", transform, [fitted[name].models[0] for name in BASE_MODELS],
                                          fitted["forest"].return_distribution)
        else:
            fitted["blend"] = fitted["forest"]
        truth.extend(y[test].tolist())
        folds += 1
        for name, model in fitted.items():
            predicted[name].extend(model.predict(x.iloc[test]).tolist())
            probabilities[name].extend(model.predict_probability(x.iloc[test]).tolist())
    limited = {"reason": "limited_validation", "family": "forest", "candidates": [],
               "folds": folds, "samples": len(truth), "selection_validated": False}
    if len(truth) < 60 or folds < 2:
        return "forest", limited
    truth = np.asarray(truth)
    candidates = []
