        values = np.asarray(values)
        candidates.append({"id": name, "mae": float(np.mean(np.abs(truth - values))),
                           "brier_score": float(np.mean((np.asarray(probabilities[name]) - (truth > 0)) ** 2)),
                           **_direction_metrics(truth, values)})
    eligible = [item for item in candidates if item["balanced_direction_accuracy"] is not None]
    if not eligible:
        return "forest", {**limited, "candidates": candidates}
    chosen = min(eligible, key=lambda item: (-item["balanced_direction_accuracy"], item["mae"],
                                            (*BASE_MODELS, "blend").index(item["id"])))
    return chosen["id"], {"reason": "direction_validation", "family": chosen["id"], "candidates": candidates,
                          "folds": folds, "samples": len(truth), "selection_validated": True,
                          "criterion": "balanced direction accuracy, then mean absolute return error"}


