def _fingerprint(frame):
    return hashlib.sha256(frame.to_csv(index=True).encode()).hexdigest()


def _public(result):
    result = copy.deepcopy(result)
    result.pop("audit", None)
    return result


def _current_result(result, now):
    result = _public(result)
    if result.get("interval") != "intraday" or result.get("status") != "ok" or not result.get("points"):
        return result
    result["points"] = [point for point in result["points"] if datetime.fromisoformat(point["trade_date"]) > now]
    if not result["points"]:
        return {**result, "status": "unavailable", "reason_code": "intraday_no_future_minutes"}
    last_step = result["points"][-1]["step"]
    for validation in result["validation"].get("by_horizon", []):
        if validation["step"] == last_step:
            result["validation"].update(validation)
            break
    return result


